import{o as t,c as i,a0 as s,j as e,t as r,p as l}from"./chunks/framework.L_oL6aia.js";const d={class:"rock-copy-email-wrapper inline"},g=JSON.parse('{"title":"Vintage Tuner Stompbox: Manual de Usuario","description":"","frontmatter":{},"headers":[],"relativePath":"es/tuner-pedal.md","filePath":"es/tuner-pedal.md"}'),c={name:"es/tuner-pedal.md"},b=Object.assign(c,{setup(u){const o=l("Copiar Correo");function n(){navigator.clipboard.writeText("mainstaudiolabs@gmail.com"),o.value="¡Copiado!",setTimeout(function(){o.value="Copiar Correo"},2e3)}return(p,a)=>(t(),i("div",null,[a[1]||(a[1]=s(`<h1 id="vintage-tuner-stompbox-manual-de-usuario" tabindex="-1">Vintage Tuner Stompbox: Manual de Usuario <a class="header-anchor" href="#vintage-tuner-stompbox-manual-de-usuario" aria-label="Permalink to &quot;Vintage Tuner Stompbox: Manual de Usuario&quot;">​</a></h1><p><strong>Versión 1.0.1 · Stompbox Series #02 · Afinador Cromático Analógico para Guitarra y Bajo</strong><br><em>Desarrollado por Main St Audio Labs · Motor DSP de Código Abierto (Licencia MIT)</em></p><img src="/TunerPedal.png" alt="Vintage Tuner Stompbox GUI" style="max-height:380px;display:block;margin:1.5rem auto;border:2px solid var(--vp-c-border);border-radius:8px;"><div style="display:flex;gap:0.75rem;justify-content:center;flex-wrap:wrap;margin:1.25rem 0 1.75rem 0;"><a href="https://github.com/mainstaudiolabs/mainstaudiolabs.github.io/releases/tag/vintage-tuner-v1.0.1" target="_blank" class="rock-btn rock-btn-primary" style="display:inline-flex;align-items:center;justify-content:center;min-width:240px;padding:0.6rem 1.4rem;text-decoration:none;">Descargar Plugin (GRATIS v1.0.1) ⬇️</a><a href="https://github.com/mainstaudiolabs/pitch-detector-tuner" target="_blank" class="rock-btn rock-btn-secondary" style="display:inline-flex;align-items:center;justify-content:center;min-width:200px;padding:0.6rem 1.2rem;text-decoration:none;">Ver Motor en GitHub (MIT) 🐙</a></div><hr><h2 id="_1-🌟-disenado-para-el-escenario-y-el-estudio" tabindex="-1">1. 🌟 Diseñado para el Escenario y el Estudio <a class="header-anchor" href="#_1-🌟-disenado-para-el-escenario-y-el-estudio" aria-label="Permalink to &quot;1. 🌟 Diseñado para el Escenario y el Estudio&quot;">​</a></h2><p>El <strong>Vintage Tuner Stompbox</strong> traslada la calidez visual y la precisión balística de los clásicos afinadores analógicos de aguja directamente a tu DAW y a tus actuaciones en vivo.</p><p>Construido con una interfaz retro fotorrealista y un motor DSP de vanguardia desarrollado por <strong>Main St Audio Labs</strong>, ofrece una respuesta de aguja firme y suave que acompaña el movimiento de tu clavijero sin saltos molestos de octava ni temblores en pantalla, funcionando con idéntica solvencia en guitarras acústicas, eléctricas, afinaciones caídas y bajos de 5 cuerdas.</p><hr><h2 id="_2-⚡-insertalo-en-todas-tus-pistas-consumo-0-0-de-cpu" tabindex="-1">2. ⚡ Insértalo en Todas tus Pistas: Consumo 0.0% de CPU <a class="header-anchor" href="#_2-⚡-insertalo-en-todas-tus-pistas-consumo-0-0-de-cpu" aria-label="Permalink to &quot;2. ⚡ Insértalo en Todas tus Pistas: Consumo 0.0% de CPU&quot;">​</a></h2><p>Uno de los mayores beneficios de Vintage Tuner Stompbox para tu flujo de trabajo en el DAW es su arquitectura <strong>True Zero-CPU Passthrough</strong>:</p><ul><li><strong>0.0% de Carga con la Ventana Cerrada:</strong> Cuando cierras la interfaz del plugin en tu DAW o apagas el interruptor <code>POWER</code>, el motor de análisis matemático se suspende de inmediato y el audio pasa en bypass transparente sin consumir un solo ciclo de CPU.</li><li><strong>Un Afinador en Cada Canal de Guitarra y Bajo:</strong> Puedes dejar insertado el afinador en <strong>todas las pistas de tu sesión</strong> listo para usar cuando lo necesites. Tu proyecto no sumará consumo de procesador adicional ni se volverá lento.</li><li><strong>Auto-Unmute de Seguridad:</strong> ¿Terminaste de afinar con el pedal en <code>MUTE</code> y cerraste la ventana para seguir grabando o mezclando? El plugin desactiva el mute automáticamente para que nunca te quede una pista silenciada por descuido en la mezcla.</li></ul><hr><h2 id="_3-🎯-doble-motor-dsp-para-guitarra-y-bajo-codigo-abierto" tabindex="-1">3. 🎯 Doble Motor DSP para Guitarra y Bajo (Código Abierto) <a class="header-anchor" href="#_3-🎯-doble-motor-dsp-para-guitarra-y-bajo-codigo-abierto" aria-label="Permalink to &quot;3. 🎯 Doble Motor DSP para Guitarra y Bajo (Código Abierto)&quot;">​</a></h2><p>El núcleo de detección de tono del pedal está impulsado por nuestra librería matemática propia, disponible de forma abierta bajo <strong>Licencia MIT</strong> en GitHub (<a href="https://github.com/mainstaudiolabs/pitch-detector-tuner" target="_blank" rel="noreferrer">pitch-detector-tuner</a>):</p><h3 id="🔀-dos-modos-de-deteccion-al-instante" tabindex="-1">🔀 Dos Modos de Detección al Instante: <a class="header-anchor" href="#🔀-dos-modos-de-deteccion-al-instante" aria-label="Permalink to &quot;🔀 Dos Modos de Detección al Instante:&quot;">​</a></h3><ul><li><strong>Modo MPM (McLeod Pitch Method):</strong> Diseñado para guitarra eléctrica y acústica. Captura al instante el ataque inicial de la púa y responde con máxima agilidad tanto en acordes abiertos como en punteos y solos rápidos.</li><li><strong>Modo YIN (De Cheveigné &amp; Kawahara):</strong> Especialmente optimizado para bajo eléctrico (4 y 5 cuerdas), guitarras de 7/8 cuerdas y afinaciones caídas (<em>Drop D, Drop C, etc.</em>). Rastrea con total estabilidad hasta la fundamental del <strong>$B_0$ (Si grave a 30.87 Hz / 25 Hz)</strong> sin confundirse con armónicos superiores.</li></ul><h3 id="🛡️-afinacion-comoda-rapida-y-estable" tabindex="-1">🛡️ Afinación Cómoda, Rápida y Estable: <a class="header-anchor" href="#🛡️-afinacion-comoda-rapida-y-estable" aria-label="Permalink to &quot;🛡️ Afinación Cómoda, Rápida y Estable:&quot;">​</a></h3><ul><li><strong>Balística de Aguja sin Oscilaciones:</strong> La aguja cuenta con un suavizado exponencial calibrado con zona muerta central ($\\pm 0.6\\text{ cents}$). Te indica con claridad si estás alto o bajo sin bailar erráticamente.</li><li><strong>Retención de Decaimiento (<em>Hold Window</em> de ~0.6 s):</strong> Cuando la vibración de la cuerda se va extinguiendo acústicamente, la aguja sostiene la última nota detectada y regresa suavemente al centro en lugar de cortarse en seco.</li><li><strong>AGC Dinámico (+41 dB Boost):</strong> Detecta pastillas pasivas <em>single-coil</em> de baja salida y sostiene notas largas sin perder la lectura.</li><li><strong>Duplicación Mono a Estéreo Automática:</strong> Si conectas tu instrumento a la entrada 1 (Mono) de tu placa, el plugin centra la señal automáticamente en ambos lados de tus monitores y auriculares.</li></ul><hr><h2 id="_4-🎛️-guia-rapida-de-controles" tabindex="-1">4. 🎛️ Guía Rápida de Controles <a class="header-anchor" href="#_4-🎛️-guia-rapida-de-controles" aria-label="Permalink to &quot;4. 🎛️ Guía Rápida de Controles&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-------------------------------------------------------------+</span></span>
<span class="line"><span>|                      [ VÚMETRO ANALÓGICO ]                  |</span></span>
<span class="line"><span>|                 b FLAT     [-50 .. 0 .. +50]     SHARP #    |</span></span>
<span class="line"><span>|                                                             |</span></span>
<span class="line"><span>|   [ MODE ]               [ DISPLAY NOTA ]         [ A4 REF ]|</span></span>
<span class="line"><span>|   MPM / YIN                E2 · 82.4 Hz           440 Hz    |</span></span>
<span class="line"><span>|                            -0.5 cents                       |</span></span>
<span class="line"><span>|                                                             |</span></span>
<span class="line"><span>|   [ MUTE ]                                        [ POWER ] |</span></span>
<span class="line"><span>|   ON / OFF                                        ON / OFF  |</span></span>
<span class="line"><span>+-------------------------------------------------------------+</span></span></code></pre></div><ul><li><strong>VÚMETRO DE AGUJA:</strong> Muestra la desviación exacta en centésimas de semitono (<code>-50</code> a <code>+50 cents</code>). La zona central ($\\pm 3\\text{ cents}$) se ilumina en verde cuando la afinación está perfecta.</li><li><strong>MODE (MPM / YIN):</strong> Conmuta entre el algoritmo para guitarra (MPM) y el algoritmo para bajo / notas graves (YIN).</li><li><strong>A4 REFERENCE (432 Hz - 448 Hz):</strong> Ajusta la frecuencia de referencia del concierto. Haz <strong>doble clic</strong> sobre el control para restablecer al estándar <strong>440 Hz</strong>.</li><li><strong>MUTE (Silent Tuning):</strong> Silencia la salida hacia tu amplificador o monitores para afinar en silencio en vivo o durante la grabación.</li><li><strong>POWER:</strong> Enciende o apaga el pedal. Al apagarlo, la aguja descansa en su posición de reposo y el audio pasa en bypass puro (0% CPU).</li><li><strong>Personalización Visual (Drag &amp; Drop):</strong> Arrastra cualquier imagen <code>.png</code> o <code>.jpg</code> sobre el pedal para cambiar la apariencia del fondo o del medidor.</li></ul><hr><h2 id="_5-💡-mejores-practicas-ubicacion-en-la-cadena-y-consejos-de-estudio" tabindex="-1">5. 💡 Mejores Prácticas: Ubicación en la Cadena y Consejos de Estudio <a class="header-anchor" href="#_5-💡-mejores-practicas-ubicacion-en-la-cadena-y-consejos-de-estudio" aria-label="Permalink to &quot;5. 💡 Mejores Prácticas: Ubicación en la Cadena y Consejos de Estudio&quot;">​</a></h2><p>Para exprimir al máximo la precisión de <strong>Vintage Tuner Stompbox</strong>, ten en cuenta estas recomendaciones de producción:</p><h3 id="🥇-colocalo-siempre-en-el-primer-slot-inicio-de-tu-cadena-fx" tabindex="-1">🥇 Colócalo Siempre en el Primer Slot (Inicio de tu Cadena FX) <a class="header-anchor" href="#🥇-colocalo-siempre-en-el-primer-slot-inicio-de-tu-cadena-fx" aria-label="Permalink to &quot;🥇 Colócalo Siempre en el Primer Slot (Inicio de tu Cadena FX)&quot;">​</a></h3><ul><li><strong>Señal Directa y Pura (DI Limpia):</strong> El afinador debe recibir la señal cruda directamente desde tu interfaz o pastillas antes de cualquier otro plugin.</li><li><strong>Evita Efectos Previos:</strong><ul><li>Las <strong>distorsiones, overdrives y fuzzes</strong> generan armónicos adicionales que saturan y enmascaran la frecuencia fundamental.</li><li>Los <strong>chorus, phasers, flangers y vibratos</strong> modulan la frecuencia en el tiempo, haciendo que la aguja oscile intentando seguir la desafinación del efecto.</li><li>Los <strong>delays y reverbs</strong> superponen ecos de notas anteriores sobre la nota que intentas afinar.</li></ul></li><li><strong>Mute Limpio en el Escenario:</strong> Al estar al inicio de la cadena, accionar el interruptor <code>MUTE</code> corta la señal antes de los amplificadores de alta ganancia, logrando silencio absoluto sin soplidos ni zumbidos.</li></ul><h3 id="🎸-consejos-de-interpretacion-para-afinar-con-maxima-precision" tabindex="-1">🎸 Consejos de Interpretación para Afinar con Máxima Precisión: <a class="header-anchor" href="#🎸-consejos-de-interpretacion-para-afinar-con-maxima-precision" aria-label="Permalink to &quot;🎸 Consejos de Interpretación para Afinar con Máxima Precisión:&quot;">​</a></h3><ul><li><strong>Usa la Pastilla del Mástil (<em>Neck Pickup</em>):</strong> La pastilla del mástil capta una mayor proporción de fundamental y menos agudos metálicos que la del puente. Si recortas levemente el potenciómetro de tono de la guitarra, la señal será aún más pura y el algoritmo responderá con velocidad quirúrgica.</li><li><strong>Pulsación Suave y Firme:</strong> Evita golpear la cuerda con excesiva fuerza (<em>pick attack</em> violento), ya que la tensión momentánea estira la cuerda y produce un leve cambio de tono transitorio (<em>pitch drift</em>). Toca con la yema del dedo o una pulsación constante a la altura del traste 12.</li><li><strong>Para Bajos de 5 Cuerdas ($B_0$ @ 25 Hz):</strong> Asegúrate de tener seleccionado el modo <strong>YIN</strong> para un seguimiento rocoso de los subgraves. También puedes afinar usando el armónico natural del traste 12 para una respuesta instantánea.</li></ul><hr><h2 id="_6-⚙️-ajustes-de-buffer-recomendados" tabindex="-1">6. ⚙️ Ajustes de Buffer Recomendados <a class="header-anchor" href="#_6-⚙️-ajustes-de-buffer-recomendados" aria-label="Permalink to &quot;6. ⚙️ Ajustes de Buffer Recomendados&quot;">​</a></h2><ul><li><strong>Escenario y Grabación en Vivo (Tracking):</strong><ul><li>Configura tu interfaz de audio en <strong>128 muestras @ 48 kHz (~2.6 ms)</strong> con drivers ASIO nativos (Windows) o CoreAudio (macOS) para una monitorización en tiempo real sin latencia ni retraso.</li></ul></li><li><strong>Sesiones de Mezcla:</strong><ul><li>Tamaños de buffer de <strong>256 a 512 muestras</strong> para proyectos con muchas pistas y cadenas de plugins pesadas.</li></ul></li></ul><hr><h2 id="_7-🔬-bajo-el-capo-ingenieria-dsp-y-estandares-en-tiempo-real" tabindex="-1">7. 🔬 Bajo el Capó: Ingeniería DSP y Estándares en Tiempo Real <a class="header-anchor" href="#_7-🔬-bajo-el-capo-ingenieria-dsp-y-estandares-en-tiempo-real" aria-label="Permalink to &quot;7. 🔬 Bajo el Capó: Ingeniería DSP y Estándares en Tiempo Real&quot;">​</a></h2><p>Para desarrolladores, técnicos de audio y entusiastas del DSP, el plugin fue programado en <strong>Modern C++ / JUCE</strong> siguiendo el <em>Estándar de Oro de Main St Audio Labs</em>:</p><ul><li><strong>Procesamiento de Audio Asíncrono:</strong> El hilo de audio real del DAW ejecuta el bloque en <code>&lt;0.5 microsegundos</code>, limitándose a escribir en un buffer circular <em>lock-free</em> de 16,384 muestras. Las matemáticas pesadas de autocorrelación (8,192 muestras) se calculan de manera independiente en un hilo secundario en segundo plano a 100 FPS, garantizando <strong>cero riesgo de <em>audio dropouts</em> o chasquidos</strong>.</li><li><strong>Cero Asignaciones Dinámicas (<code>malloc</code>/<code>new</code>):</strong> Toda la memoria DSP y los buffers se pre-asignan en <code>prepareToPlay()</code>.</li><li><strong>Protección contra Números Denormales (<code>ScopedNoDenormals</code>):</strong> Evita picos innecesarios de CPU en silencio.</li><li><strong>Portabilidad Total con <code>BinaryData</code>:</strong> Todos los gráficos y texturas están compilados dentro del propio archivo del plugin. No requiere instaladores complejos ni carpetas sueltas de imágenes.</li><li><strong>Repositorio Open Source:</strong> La implementación matemática de los detectores YIN y MPM se encuentra disponible en GitHub bajo Licencia MIT:<br> 👉 <a href="https://github.com/mainstaudiolabs/pitch-detector-tuner" target="_blank" rel="noreferrer">https://github.com/mainstaudiolabs/pitch-detector-tuner</a></li></ul><hr><h2 id="_8-💻-compatibilidad-y-descargas" tabindex="-1">8. 💻 Compatibilidad y Descargas <a class="header-anchor" href="#_8-💻-compatibilidad-y-descargas" aria-label="Permalink to &quot;8. 💻 Compatibilidad y Descargas&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Sistema Operativo</th><th style="text-align:left;">Formatos</th><th style="text-align:left;">Requisitos</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Windows</strong></td><td style="text-align:left;">VST3 (64-bit), Standalone (<code>.exe</code>)</td><td style="text-align:left;">Windows 10 / 11 (64-bit)</td></tr><tr><td style="text-align:left;"><strong>macOS</strong></td><td style="text-align:left;">VST3, AU (<code>.component</code>), Standalone (<code>.app</code>)</td><td style="text-align:left;">macOS 10.13+ (Universal: Apple Silicon M1/M2/M3 e Intel)</td></tr><tr><td style="text-align:left;"><strong>Linux</strong></td><td style="text-align:left;">VST3 (64-bit), Standalone ejecutable</td><td style="text-align:left;">Ubuntu 22.04+ o distros compatibles (x64)</td></tr></tbody></table><ul><li><strong>Instalación:</strong> Simplemente descomprime el archivo descargado y copia el <code>.vst3</code> en tu carpeta habitual de plugins (ej. <code>C:\\Program Files\\Common Files\\VST3\\</code> en Windows).</li></ul><div style="margin:1.5rem 0;text-align:center;"><a href="https://github.com/mainstaudiolabs/mainstaudiolabs.github.io/releases/tag/vintage-tuner-v1.0.1" target="_blank" class="rock-btn rock-btn-primary" style="display:inline-flex;align-items:center;justify-content:center;min-width:250px;padding:0.65rem 1.6rem;text-decoration:none;font-size:1rem;">Descargar Vintage Tuner Stompbox (GRATIS) ⬇️</a></div><hr><h2 id="_9-📄-licencia-y-terminos" tabindex="-1">9. 📄 Licencia y Términos <a class="header-anchor" href="#_9-📄-licencia-y-terminos" aria-label="Permalink to &quot;9. 📄 Licencia y Términos&quot;">​</a></h2><ul><li>El plugin <strong>Vintage Tuner Stompbox</strong> se distribuye como <strong>Freeware (Gratuito)</strong> bajo el EULA de Main St Audio Labs para uso personal y producciones comerciales.</li><li>El motor DSP subyacente es <strong>Open Source (Licencia MIT)</strong> y puede consultarse en <a href="https://github.com/mainstaudiolabs/pitch-detector-tuner" target="_blank" rel="noreferrer">pitch-detector-tuner</a>.</li></ul><hr><h3 id="¡queremos-conocer-tu-experiencia" tabindex="-1">¡Queremos conocer tu experiencia! <a class="header-anchor" href="#¡queremos-conocer-tu-experiencia" aria-label="Permalink to &quot;¡Queremos conocer tu experiencia!&quot;">​</a></h3><p>Envíanos tus comentarios, sugerencias o dudas a nuestro correo oficial:</p>`,48)),e("div",d,[a[0]||(a[0]=e("span",{class:"rock-email-text"},"mainstaudiolabs@gmail.com",-1)),e("button",{class:"rock-copy-btn",onClick:n},r(o.value),1)]),a[2]||(a[2]=e("p",{style:{"margin-top":"2rem","margin-bottom":"1rem"}},"Si deseas apoyar nuestra investigación independiente y ayudarnos a mantener nuestros plugins gratuitos, puedes apoyarnos con Tarjeta, PayPal o Criptomonedas:",-1)),a[3]||(a[3]=e("div",null,[e("a",{href:"/es/support",class:"rock-btn rock-btn-primary",style:{display:"inline-block","text-align":"center"}},"Apoya el Laboratorio (Ko-fi / Crypto) ☕")],-1))]))}});export{g as __pageData,b as default};
